    "nameKo": "3D 클레이/블라인드박스",
    "promptZh": "3D 粘土塑形风格，极简主义粘土质感，柔和马卡龙配色，细腻磨砂表面纹理，哑光材质，具有明显厚度和圆润边缘倒角。光影呈现柔和全局照明，伴有细腻软阴影和微弱反光，展现出类似橡皮泥或合成树脂的触感。构图简洁，具有高饱和度现代潮玩视觉感。",
