    "promptZh": "3D果冻珠宝科技风格：核心是像果冻、玻璃糖、透明树脂、水晶宝石一样的高透材质。角色或物体应呈现圆润厚实的软胶轮廓、半透明体积、内部颜色渐变、清晰折射、焦散光、高亮反光边缘和珠宝级抛光表面整体晶莹剔透、湿润、光滑、可爱但高级。色彩关键词：透明果冻色、乳白半透明、玻璃高光、柔和粉橙、浅色背景。光影关键词：棚拍柔光、强镜面高光、透明折射光、焦散投影、边缘透光、柔和阴影。材质关键词：透明树脂、果冻玻璃、琉璃、水晶、抛光宝石、软胶厚边、内部气泡、次表面散射。镜头关键词：3D产品摄影、微距质感展示、浅景深、干净居中构图、PBR高质量渲染。环境关键词：浅色摄影棚、白色背景、柔和反光台面、干净产品展示空间。生成时必须把所有服装、头发、配饰或主体转译为果冻珠宝般的半透明材质，避免脏乱背景和普通塑料。",
    "promptEn": "3D Jelly Jewelry Tech Style: The core is highly transparent materials like jelly, glass candy, clear resin, and crystal gems. Characters or objects should have a rounded, chubby soft rubber silhouette, translucent volume, internal color gradients, clear refraction, caustic light, bright reflective edges, and jewelry-grade polished surfaces, overall crystal clear, moist, smooth, cute yet premium. Color keywords: transparent jelly colors, milky translucency, glass highlights, soft pink-orange, light background."
