    "promptZh": "Render the requested subject and scene as a bright 2.5D anime CG animation still with a warm near-future summer feeling. Keep the user's content, layout, subject type, and camera request unchanged. Use a stylized anime look that blends 3D volume with hand-painted cel-animation edges. When characters are present, give them youthful anime proportions, expressive glossy eyes, detailed soft hair, appealing facial shapes, and semi-realistic skin texture: subtle pores, soft freckles when suitable, cheek redness, realistic nose and lip highlights, slight skin translucency, fine eyelashes, and warm sunlit facial shading. Characters should feel alive and tactile, not plastic, while staying clearly anime-stylized. Use strong clear daylight with a warm sunlit color grade: golden highlights, warm skin tones, amber accents, vivid reds and yellows, balanced by deep blue skies and cool cyan shadows when appropriate. Keep the palette saturated, fresh, cheerful, and clean, with soft bloom, sharp sunlit edges, gentle haze, and low-to-medium contrast shadows. Give the world a colorful near-future anime design language without forcing a specific location: sleek shapes, playful tech details, decals, signage-like accents, worn painted metal, stickers, scratches, panels, mechanical parts, glossy plastic, fabric texture, and lived-in futuristic objects when suitable. Use dynamic anime framing: wide-angle perspective, energetic composition, strong depth, close-up distortion when appropriate, large sky or open space when the scene allows, crisp foreground detail, and softer painterly background depth. The final image should feel vivid, sunlit, youthful, slightly futuristic, hand-drawn in finish but volumetric in form.",
