    "promptEn": "Traditional Edo-period Ukiyo-e style, with woodblock-print quality. It features delicate, smooth outlines; lines are fluid and elastic. In color it uses soft, historically weathered low-saturation mineral tones, supplemented by large areas of flat color and elegant color contrast (such as deep purple, vermilion, and ink green). The background presents a fine antique washi fiber texture, bearing slight traces of age and a mottled quality. The overall visual presents an Eastern classical flattened composition, a flat sense of perspective, and a tranquil, refined artistic conception. Breakdown of core style elements: Line: extremely precise, soft and fine ink outlines. Color: traditional Japanese five-color flat fills, with clearly delineated color blocks. Texture: a pronounced aging-paper ground tone."
