    "promptEn": "Pop Art style. It presents a highly iconic, rough-hewn Pop Art style. The precise style descriptors are as follows: High-saturation contrast: uses a limited set of extremely vivid, strongly contrasting solid color blocks (such as bright pink, bright yellow, electric blue, and deep cyan). Halftone dot texture: the face and hair of the image are constructed from coarse, clearly visible mechanical halftone dots (Ben-Day dots), imitating a cheap four-color printing effect. Screen print effect: slight misregistration between color layers and uneven ink coverage, expressing a rough, hand-printed quality. Grunge/Distressed: the entire image, especially the background, is covered with abundant wear, scratches, stains, and rough scratch textures, lending it a retro, underground, weather-beaten quality. Screen mesh artifacts: in certain solid-color areas and at the edges of dots, fine patterns or textures resembling screen mesh are visible. Flattening and contouring: shadows and highlights are simplified into large, solid dark-gray or black flat contours, lacking delicate transitions."
