export const styleGroups = [
  { key: "realistic", label: "真人", styles: styleLibrary.filter(item => item.groupKey === "realistic") },
  { key: "3d-special", label: "3D", styles: styleLibrary.filter(item => item.groupKey === "3d-special") },
  { key: "2d", label: "2D", styles: styleLibrary.filter(item => item.groupKey === "2d") },
] as const;

export const styleByKey = new Map(styleLibrary.map(item => [item.key, item]));

export function getStylePrompt(styleKey?: string) {
  if (!styleKey) return "";
  return styleByKey.get(styleKey)?.promptZh.trim() ?? "";
}

export function appendStylePrompt(prompt: string, styleKey?: string) {
  const style = styleByKey.get(styleKey ?? "");
  if (!style) return prompt.trim();
  return [prompt.trim(), `【画风】${style.nameZh}：${style.promptZh.trim()}`].filter(Boolean).join("\n\n");
}
